"cmd": "gcloud compute backend-buckets create static-bb --gcs-bucket-name=shop-static --enable-cdn\ngcloud compute backend-services update web-be --global --enable-cdn \\\n  --cache-mode=CACHE_ALL_STATIC --default-ttl=3600\n\ngcloud compute url-maps invalidate-cdn-cache shop-map --path=\"/images/*\" --global",
